pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dynamic horizon awareness
    let step_weight = 1.0 + (total_jobs - step_index) as f64 / total_jobs as f64;

    // Lookahead awareness for perfect fit
    let next_job_perfect_fit = job_cpu <= node_residual_cpu && job_ram <= node_residual_ram;
    let lookahead_penalty = if next_job_perfect_fit { 0.0 } else { 1.0 };

    let score = cpu_norm + ram_norm - imbalance_penalty + step_weight * lookahead_penalty;
    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = (node_residual_cpu as f64 - job_cpu as f64) / node_capacity_cpu as f64;
    let ram_norm = (node_residual_ram as f64 - job_ram as f64) / node_capacity_ram as f64;
    let imbalance_penalty = ((cpu_norm - ram_norm).abs()).powi(2);

    // Lookahead packing bonus
    let lookahead_bonus = if next_job_cpu <= node_residual_cpu && next_job_ram <= node_residual_ram { 0.1 } else { 0.0 };

    // Horizon-aware placement logic
    let horizon_factor = step_index as f64 / total_jobs as f64;
    let horizon_penalty = (horizon_factor - 0.5).abs() * 2.0;

    // Combined score
    imbalance_penalty + lookahead_bonus - horizon_penalty
}
